import { describe, expect, test, vi } from "vitest";

import {
  manualOauthClient,
  MAX_CLIENT_ID_LENGTH,
  OauthRegistrationError,
  registerOauthClient
} from "./agent-vault-oauth-client-fns";
import { TOauthHttpClient, TOauthHttpResponse } from "./agent-vault-oauth-http-fns";
import { AgentVaultOauthClientAuthMethod, AgentVaultOauthCompatibility } from "./agent-vault-oauth-types";

vi.mock("@app/lib/logger", async () => ({
  logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() },
  sanitizeUrlForLog: (
    await vi.importActual<typeof import("@app/lib/logger/sanitize-url")>("@app/lib/logger/sanitize-url")
  ).sanitizeUrlForLog
}));

const stubPosts = (responses: TOauthHttpResponse[]) => {
  const calls: { url: string; json: unknown }[] = [];
  const http: TOauthHttpClient = {
    probe: async () => ({ status: 401, wwwAuthenticate: null }),
    get: async () => {
      throw new Error("unexpected");
    },
    postForm: async () => {
      throw new Error("unexpected");
    },
    postJson: async (url, json) => {
      calls.push({ url, json });
      const response = responses.shift();
      if (!response) throw new Error("no more stubbed responses");
      return response;
    }
  };
  return { http, calls };
};

const json = (status: number, body: unknown): TOauthHttpResponse => ({
  status,
  contentType: "application/json",
  body: JSON.stringify(body)
});

describe("client registration", () => {
  const args = {
    serverUrl: "https://mcp.example.com/mcp",
    registrationEndpoint: "https://mcp.example.com/register",
    redirectUri: "https://app.infisical.com/agent-vault/oauth/callback",
    grantTypesSupported: null,
    tokenEndpointAuthMethodsSupported: null
  };

  test("sends the full metadata and keeps the method the server assigned", async () => {
    const { http, calls } = stubPosts([
      json(201, { client_id: "c-1", client_secret: "s-1", token_endpoint_auth_method: "client_secret_post" })
    ]);
    expect(await registerOauthClient({ http, ...args })).toEqual({
      client: {
        clientId: "c-1",
        clientSecret: "s-1",
        tokenEndpointAuthMethod: AgentVaultOauthClientAuthMethod.ClientSecretPost
      },
      compatibility: []
    });
    expect(calls[0].json).toEqual({
      client_name: "Infisical Agent Vault",
      redirect_uris: [args.redirectUri],
      token_endpoint_auth_method: "none",
      application_type: "web",
      grant_types: ["authorization_code", "refresh_token"],
      response_types: ["code"]
    });
  });

  test("asks for refresh_token only when the server doesn't list grants without it", async () => {
    const { http, calls } = stubPosts([json(201, { client_id: "c-1" })]);
    await registerOauthClient({ http, ...args, grantTypesSupported: ["authorization_code"] });
    expect(calls[0].json).toMatchObject({ grant_types: ["authorization_code"] });
  });

  test("asks for a confidential client when the server lists its auth methods without none", async () => {
    const { http, calls } = stubPosts([json(201, { client_id: "c-3", client_secret: "s-3" })]);
    const result = await registerOauthClient({
      http,
      ...args,
      tokenEndpointAuthMethodsSupported: ["client_secret_post"]
    });
    expect(calls[0].json).toMatchObject({ token_endpoint_auth_method: "client_secret_post" });
    expect(result.client).toEqual({
      clientId: "c-3",
      clientSecret: "s-3",
      tokenEndpointAuthMethod: AgentVaultOauthClientAuthMethod.ClientSecretPost
    });

    const both = stubPosts([json(201, { client_id: "c-4" })]);
    await registerOauthClient({
      http: both.http,
      ...args,
      tokenEndpointAuthMethodsSupported: ["client_secret_basic", "none"]
    });
    expect(both.calls[0].json).toMatchObject({ token_endpoint_auth_method: "none" });
  });

  test("a rejected registration is retried once without application_type, keeping the grant types", async () => {
    const { http, calls } = stubPosts([
      json(400, { error: "invalid_client_metadata" }),
      json(201, { client_id: "c-2" })
    ]);
    const result = await registerOauthClient({ http, ...args });
    expect(result.client).toEqual({ clientId: "c-2", tokenEndpointAuthMethod: AgentVaultOauthClientAuthMethod.None });
    expect(result.compatibility).toEqual([AgentVaultOauthCompatibility.RegistrationMinimal]);
    expect(calls[1].json).toEqual({
      client_name: "Infisical Agent Vault",
      redirect_uris: [args.redirectUri],
      token_endpoint_auth_method: "none",
      grant_types: ["authorization_code", "refresh_token"],
      response_types: ["code"]
    });
  });

  test("two refusals, or a server error, end in a registration error", async () => {
    const refused = stubPosts([json(400, {}), json(403, {})]);
    await expect(registerOauthClient({ http: refused.http, ...args })).rejects.toBeInstanceOf(OauthRegistrationError);

    const broken = stubPosts([json(503, {})]);
    await expect(registerOauthClient({ http: broken.http, ...args })).rejects.toThrow(/HTTP 503/);
    expect(broken.calls).toHaveLength(1);
  });

  test("the server's reason for refusing is passed on", async () => {
    const { http } = stubPosts([
      json(400, { error: "invalid_redirect_uri", error_description: "Plaintext HTTP is allowed only for loopback." }),
      json(400, { error: "invalid_redirect_uri", error_description: "Plaintext HTTP is allowed only for loopback." })
    ]);
    await expect(registerOauthClient({ http, ...args })).rejects.toThrow(
      "its registration endpoint refused to register Infisical as a client (Plaintext HTTP is allowed only for loopback.)."
    );
  });

  test("a long JWT client ID is accepted, up to the limit", async () => {
    const jwtLength = stubPosts([json(201, { client_id: "c".repeat(850) })]);
    expect((await registerOauthClient({ http: jwtLength.http, ...args })).client.clientId).toHaveLength(850);

    const tooLong = stubPosts([json(201, { client_id: "c".repeat(MAX_CLIENT_ID_LENGTH + 1) })]);
    await expect(registerOauthClient({ http: tooLong.http, ...args })).rejects.toThrow(/no usable client ID/);
  });

  test("a client ID or secret that isn't printable ASCII is no usable client", async () => {
    const badId = stubPosts([json(201, { client_id: "c\u0000" })]);
    await expect(registerOauthClient({ http: badId.http, ...args })).rejects.toThrow(/no usable client ID/);

    const badSecret = [REDACTED], { client_id: "c", client_secret: "s\ud800" })]);
    await expect(registerOauthClient({ http: badSecret.http, ...args })).rejects.toThrow(/no usable client ID/);
  });

  test("the refusal reason is normalized, the error code included", async () => {
    const { http } = stubPosts([json(400, { error: "bad\u0000request" }), json(400, { error: "bad\u0000request" })]);
    await expect(registerOauthClient({ http, ...args })).rejects.toThrow(
      "its registration endpoint refused to register Infisical as a client (bad request)."
    );
  });

  test("a manual client picks basic unless the server lists only post", () => {
    expect(manualOauthClient({ clientId: "c", tokenEndpointAuthMethodsSupported: null })).toEqual({
      clientId: "c",
      tokenEndpointAuthMethod: AgentVaultOauthClientAuthMethod.None
    });
    expect(
      manualOauthClient({ clientId: "c", clientSecret: "s", tokenEndpointAuthMethodsSupported: null })
        .tokenEndpointAuthMethod
    ).toBe(AgentVaultOauthClientAuthMethod.ClientSecretBasic);
    expect(
      manualOauthClient({
        clientId: "c",
        clientSecret: "s",
        tokenEndpointAuthMethodsSupported: ["client_secret_post"]
      }).tokenEndpointAuthMethod
    ).toBe(AgentVaultOauthClientAuthMethod.ClientSecretPost);
  });
});

import { AgentVaultBearerConfigSchema } from "./agent-vault-credential-schemas";

describe("bearer credential config", () => {
  test("Authorization and Bearer settle together when neither is given", () => {
    expect(AgentVaultBearerConfigSchema.parse({})).toEqual({
      headerName: "Authorization",
      headerPrefix: "Bearer"
    });
  });

  test("naming Authorization outright still gets the scheme it belongs to", () => {
    expect(AgentVaultBearerConfigSchema.parse({ headerName: "authorization" })).toEqual({
      headerName: "authorization",
      headerPrefix: "Bearer"
    });
  });

  // The scheme is RFC 6750's for Authorization. A key in its own header is not a bearer token in that
  // sense, and an API given "Bearer abc" where it wanted "abc" rejects the request.
  test("a header of the caller's own gets no scheme they did not ask for", () => {
    expect(AgentVaultBearerConfigSchema.parse({ headerName: "X-Api-Key" })).toEqual({
      headerName: "X-Api-Key",
      headerPrefix: ""
    });
  });

  test("an explicit prefix is kept, on any header", () => {
    expect(AgentVaultBearerConfigSchema.parse({ headerName: "X-Api-Key", headerPrefix: "Token" })).toEqual({
      headerName: "X-Api-Key",
      headerPrefix: "Token"
    });
    expect(AgentVaultBearerConfigSchema.parse({ headerPrefix: "" })).toEqual({
      headerName: "Authorization",
      headerPrefix: ""
    });
  });
});

import { Knex } from "knex";

import { TableName } from "../schemas";
import { createOnUpdateTrigger, dropOnUpdateTrigger } from "../utils";

export async function up(knex: Knex): Promise<void> {
  const hasAllowedMethods = await knex.schema.hasColumn(TableName.AgentVaultService, "allowedMethods");
  const hasAllowedPathPrefixes = await knex.schema.hasColumn(TableName.AgentVaultService, "allowedPathPrefixes");

  if (!hasAllowedMethods || !hasAllowedPathPrefixes) {
    await knex.schema.alterTable(TableName.AgentVaultService, (t) => {
      // NULL is the only "unrestricted": an empty array is never stored, so there is one representation of "all".
      // Arrays rather than the comma-separated strings hostPattern uses, because a comma is legal in a path.
      if (!hasAllowedMethods) t.specificType("allowedMethods", "text[]");
      if (!hasAllowedPathPrefixes) t.specificType("allowedPathPrefixes", "text[]");
    });
  }

  if (!(await knex.schema.hasTable(TableName.AgentVaultServiceCustomHeader))) {
    await knex.schema.createTable(TableName.AgentVaultServiceCustomHeader, (t) => {
      t.uuid("id", { primaryKey: true }).defaultTo(knex.fn.uuid());

      t.uuid("serviceId").notNullable();
      t.foreign("serviceId").references("id").inTable(TableName.AgentVaultService).onDelete("CASCADE");
      t.index("serviceId");

      t.string("name", 128).notNullable();
      t.string("prefix", 64).notNullable();

      t.binary("encryptedValue").notNullable();

      t.integer("position").notNullable();

      t.timestamps(true, true, true);
    });

    await createOnUpdateTrigger(knex, TableName.AgentVaultServiceCustomHeader);
  }

  if (!(await knex.schema.hasTable(TableName.AgentVaultServiceSubstitution))) {
    await knex.schema.createTable(TableName.AgentVaultServiceSubstitution, (t) => {
      t.uuid("id", { primaryKey: true }).defaultTo(knex.fn.uuid());

      t.uuid("serviceId").notNullable();
      t.foreign("serviceId").references("id").inTable(TableName.AgentVaultService).onDelete("CASCADE");
      t.index("serviceId");

      t.string("placeholder", 255).notNullable();
      t.specificType("surfaces", "text[]").notNullable();

      t.binary("encryptedValue").notNullable();

      t.integer("position").notNullable();

      t.timestamps(true, true, true);
    });

    await createOnUpdateTrigger(knex, TableName.AgentVaultServiceSubstitution);
  }
}

export async function down(knex: Knex): Promise<void> {
  await knex.schema.dropTableIfExists(TableName.AgentVaultServiceSubstitution);
  await dropOnUpdateTrigger(knex, TableName.AgentVaultServiceSubstitution);

  await knex.schema.dropTableIfExists(TableName.AgentVaultServiceCustomHeader);
  await dropOnUpdateTrigger(knex, TableName.AgentVaultServiceCustomHeader);

  const hasAllowedMethods = await knex.schema.hasColumn(TableName.AgentVaultService, "allowedMethods");
  const hasAllowedPathPrefixes = await knex.schema.hasColumn(TableName.AgentVaultService, "allowedPathPrefixes");

  if (hasAllowedMethods || hasAllowedPathPrefixes) {
    await knex.schema.alterTable(TableName.AgentVaultService, (t) => {
      if (hasAllowedMethods) t.dropColumn("allowedMethods");
      if (hasAllowedPathPrefixes) t.dropColumn("allowedPathPrefixes");
    });
  }
}

import { TAgentVaultServices } from "@app/db/schemas";

import { AgentVaultCredentialType } from "../agent-vault/agent-vault-enums";
import { TAgentVaultCredentialUpdate } from "./agent-vault-access-bundle-types";
import {
  isStoredSecretReplaced,
  mergeCredential,
  needsStoredSecretFor,
  splitCredential
} from "./agent-vault-credential-write-fns";

const VALUE = "credential-value";
const USERNAME = "credential-username";

const BEARER = AgentVaultCredentialType.Bearer;
const BASIC = AgentVaultCredentialType.Basic;
const PASSTHROUGH = AgentVaultCredentialType.Passthrough;

// Only the columns the helpers read. A sealed secret is any non-empty buffer: the helpers check for one, not its contents.
const storedService = ({
  type,
  memberProvidedFields = null,
  sealed = true
}: {
  type: AgentVaultCredentialType;
  memberProvidedFields?: string[] | null;
  sealed?: boolean;
}) =>
  ({
    credentialType: type,
    credentialConfig: type === BEARER ? { type, headerName: "Authorization", headerPrefix: "Bearer " } : { type },
    memberProvidedFields,
    encryptedCredential: sealed ? Buffer.from("sealed") : null
  }) as unknown as TAgentVaultServices;

const credential = (value: Record<string, unknown>) => value as unknown as TAgentVaultCredentialUpdate;

describe("splitCredential", () => {
  test.each([
    ["bearer with a token", { type: BEARER, value: "t" }, { value: "t" }, null],
    ["bearer left to members", { type: BEARER, memberProvidedFields: [VALUE] }, null, [VALUE]],
    ["basic with both halves", { type: BASIC, username: "u", password: "p" }, { username: "u", password: "p" }, null],
    ["basic with a username only", { type: BASIC, username: "u" }, { username: "u", password: "" }, null],
    [
      "basic with the password left to members",
      { type: BASIC, username: "u", memberProvidedFields: [VALUE] },
      { username: "u" },
      [VALUE]
    ],
    ["basic left wholly to members", { type: BASIC, memberProvidedFields: [USERNAME, VALUE] }, null, [USERNAME, VALUE]],
    ["passthrough", { type: PASSTHROUGH }, null, null]
  ])("%s", (_, input, secret, memberProvidedFields) => {
    const written = splitCredential(credential(input));
    expect(written.secret).toEqual(secret);
    expect(written.memberProvidedFields).toEqual(memberProvidedFields);
  });

  test.each([
    ["bearer with no token and nothing left to members", { type: BEARER }, "needs a token"],
    ["basic with neither half", { type: BASIC }, "needs a username, a password, or both"]
  ])("refuses %s", (_, input, message) => {
    expect(() => splitCredential(credential(input))).toThrow(message);
  });
});

describe("mergeCredential", () => {
  const STORED_BASIC = { username: "stored-u", password: "stored-p" };

  test.each([
    // [case, stored service, update, sealed secret read for it, expected secret, expected member fields]
    ["bearer token rotated", { type: BEARER }, { type: BEARER, value: "new" }, null, { value: "new" }, null],
    ["bearer header renamed only", { type: BEARER }, { type: BEARER, headerName: "X-Key" }, null, undefined, null],
    [
      "bearer token handed to members",
      { type: BEARER },
      { type: BEARER, memberProvidedFields: [VALUE] },
      null,
      null,
      [VALUE]
    ],
    [
      "bearer still member provided, list left out",
      { type: BEARER, memberProvidedFields: [VALUE], sealed: false },
      { type: BEARER, headerName: "X-Key" },
      null,
      undefined,
      [VALUE]
    ],
    [
      "bearer taken back with a token",
      { type: BEARER, memberProvidedFields: [VALUE], sealed: false },
      { type: BEARER, memberProvidedFields: [], value: "admin" },
      null,
      { value: "admin" },
      null
    ],
    [
      "basic password rotated",
      { type: BASIC },
      { type: BASIC, password: "new-p" },
      STORED_BASIC,
      { username: "stored-u", password: "new-p" },
      null
    ],
    [
      "basic password handed to members",
      { type: BASIC },
      { type: BASIC, memberProvidedFields: [VALUE] },
      STORED_BASIC,
      { username: "stored-u" },
      [VALUE]
    ],
    [
      "basic password taken back with a value",
      { type: BASIC, memberProvidedFields: [VALUE] },
      { type: BASIC, memberProvidedFields: [], password: "admin-p" },
      { username: "stored-u" },
      { username: "stored-u", password: "admin-p" },
      null
    ],
    [
      "basic password taken back without one starts it empty",
      { type: BASIC, memberProvidedFields: [VALUE] },
      { type: BASIC, memberProvidedFields: [] },
      { username: "stored-u" },
      { username: "stored-u", password: "" },
      null
    ],
    [
      "basic username taken back from a fully member-provided credential",
      { type: BASIC, memberProvidedFields: [USERNAME, VALUE], sealed: false },
      { type: BASIC, memberProvidedFields: [VALUE] },
      null,
      { username: "" },
      [VALUE]
    ],
    [
      "basic username handed over as well",
      { type: BASIC, memberProvidedFields: [VALUE] },
      { type: BASIC, memberProvidedFields: [USERNAME, VALUE] },
      { username: "stored-u" },
      null,
      [USERNAME, VALUE]
    ],
    ["basic unchanged", { type: BASIC }, { type: BASIC }, null, undefined, null],
    [
      "type changed to a member-provided bearer",
      { type: BASIC },
      { type: BEARER, memberProvidedFields: [VALUE] },
      null,
      null,
      [VALUE]
    ],
    ["type changed to passthrough", { type: BEARER }, { type: PASSTHROUGH }, null, null, null]
  ])("%s", (_, stored, update, sealedSecret, secret, memberProvidedFields) => {
    const written = mergeCredential(
      credential(update),
      storedService(stored as Parameters<typeof storedService>[0]),
      sealedSecret
    );
    expect(written.secret).toEqual(secret);
    expect(written.memberProvidedFields).toEqual(memberProvidedFields);
  });

  test.each([
    [
      "a token sent for a member-provided field",
      { type: BEARER, memberProvidedFields: [VALUE], sealed: false },
      { type: BEARER, value: "x" },
      "is member provided"
    ],
    [
      "a bearer taken back with no token",
      { type: BEARER, memberProvidedFields: [VALUE], sealed: false },
      { type: BEARER, memberProvidedFields: [] },
      "Provide a token when you stop leaving it to each member"
    ],
    [
      "a type change to bearer with no token",
      { type: BASIC },
      { type: BEARER },
      "Provide a new token when changing the credential type to bearer"
    ],
    [
      "a basic left with neither half",
      { type: BASIC, memberProvidedFields: [USERNAME, VALUE], sealed: false },
      { type: BASIC, memberProvidedFields: [] },
      "needs a username, a password, or both"
    ]
  ])("refuses %s", (_, stored, update, message) => {
    expect(() =>
      mergeCredential(credential(update), storedService(stored as Parameters<typeof storedService>[0]), null)
    ).toThrow(message);
  });
});

describe("isStoredSecretReplaced", () => {
  test.each([
    ["a token sent", { type: BEARER }, { type: BEARER, value: "new" }, { value: "new" }, true],
    ["nothing written", { type: BEARER }, { type: BEARER, headerName: "X" }, undefined, false],
    ["a stored token handed to members", { type: BEARER }, { type: BEARER, memberProvidedFields: [VALUE] }, null, true],
    [
      "a stored password handed to members",
      { type: BASIC },
      { type: BASIC, memberProvidedFields: [VALUE] },
      { username: "u" },
      true
    ],
    [
      "a member-provided password taken back empty",
      { type: BASIC, memberProvidedFields: [VALUE] },
      { type: BASIC, memberProvidedFields: [] },
      { username: "u", password: "" },
      false
    ],
    ["a type change over a stored secret", { type: BEARER }, { type: PASSTHROUGH }, null, true],
    [
      "a type change with nothing stored before or after",
      { type: PASSTHROUGH, sealed: false },
      { type: BEARER, memberProvidedFields: [VALUE] },
      null,
      false
    ]
  ])("%s", (_, stored, update, written, replaced) => {
    expect(
      isStoredSecretReplaced(
        credential(update),
        storedService(stored as Parameters<typeof storedService>[0]),
        written as Record<string, string> | null | undefined
      )
    ).toBe(replaced);
  });
});

describe("needsStoredSecretFor", () => {
  test.each([
    ["a basic password rotated keeps the stored username", { type: BASIC }, { type: BASIC, password: "p" }, true],
    ["a basic with both halves sent", { type: BASIC }, { type: BASIC, username: "u", password: "p" }, false],
    ["a basic left unchanged", { type: BASIC }, { type: BASIC }, false],
    [
      "a basic password handed to members keeps the stored username",
      { type: BASIC },
      { type: BASIC, memberProvidedFields: [VALUE] },
      true
    ],
    [
      "a basic half taken back has nothing stored to keep",
      { type: BASIC, memberProvidedFields: [USERNAME, VALUE] },
      { type: BASIC, memberProvidedFields: [VALUE] },
      false
    ],
    ["a basic with nothing sealed", { type: BASIC, sealed: false }, { type: BASIC, password: "p" }, false],
    ["a bearer", { type: BEARER }, { type: BEARER, value: "t" }, false],
    ["a type change", { type: BEARER }, { type: BASIC, password: "p" }, false]
  ])("%s", (_, stored, update, needed) => {
    expect(needsStoredSecretFor(credential(update), storedService(stored as Parameters<typeof storedService>[0]))).toBe(
      needed
    );
  });
});

import { logger } from "@app/lib/logger";
import { OauthGrantType } from "@app/services/oauth-client/oauth-client-types";

import { describeServer } from "./agent-vault-oauth-discovery-fns";
import { TOauthHttpClient, withTimeout } from "./agent-vault-oauth-http-fns";
import {
  MAX_ERROR_CODE_LENGTH,
  MAX_ERROR_DESCRIPTION_LENGTH,
  normalizeProviderText,
  OAUTH_VSCHAR_PATTERN
} from "./agent-vault-oauth-token-fns";
import { AgentVaultOauthClientAuthMethod, AgentVaultOauthCompatibility } from "./agent-vault-oauth-types";

const AGENT_VAULT_OAUTH_CLIENT_NAME = "Infisical Agent Vault";

// Shared by both registration attempts, so authorization creation answers well inside the gateway timeout.
const REGISTRATION_BUDGET_MS = 15_000;

export type TOauthClient = {
  clientId: string;
  clientSecret?: string;
  tokenEndpointAuthMethod: AgentVaultOauthClientAuthMethod;
};

export class OauthRegistrationError extends Error {
  status: number | null;

  constructor(message: string, status: number | null) {
    super(message);
    this.name = "OauthRegistrationError";
    this.status = status;
  }
}

const SUPPORTED_AUTH_METHODS = Object.values(AgentVaultOauthClientAuthMethod) as string[];

export const MAX_CLIENT_ID_LENGTH = 2048;
export const MAX_CLIENT_SECRET_LENGTH = 4096;

const parseRegistration = (body: string, requestedMethod: AgentVaultOauthClientAuthMethod): TOauthClient | null => {
  let parsed: Record<string, unknown>;
  try {
    parsed = JSON.parse(body) as Record<string, unknown>;
  } catch {
    return null;
  }
  if (
    !parsed ||
    typeof parsed.client_id !== "string" ||
    parsed.client_id.length > MAX_CLIENT_ID_LENGTH ||
    !OAUTH_VSCHAR_PATTERN.test(parsed.client_id)
  ) {
    return null;
  }
  let clientSecret: string | undefined;
  if (typeof parsed.client_secret === "string" && parsed.client_secret) {
    if (parsed.client_secret.length > MAX_CLIENT_SECRET_LENGTH || !OAUTH_VSCHAR_PATTERN.test(parsed.client_secret)) {
      return null;
    }
    clientSecret = [REDACTED];
  }
  // The server may assign a method other than the one asked for; what it returns is what the client holds.
  let method = typeof parsed.token_endpoint_auth_method === "string" ? parsed.token_endpoint_auth_method : null;
  if (!method || !SUPPORTED_AUTH_METHODS.includes(method)) {
    if (!clientSecret) method = AgentVaultOauthClientAuthMethod.None;
    else if (requestedMethod !== AgentVaultOauthClientAuthMethod.None) method = requestedMethod;
    else method = AgentVaultOauthClientAuthMethod.ClientSecretBasic;
  }
  return {
    clientId: parsed.client_id,
    clientSecret,
    tokenEndpointAuthMethod: method as AgentVaultOauthClientAuthMethod
  };
};

// RFC 8414 makes client_secret_basic the default when the server lists no methods.
const secretAuthMethod = (supported: string[] | null) =>
  supported &&
  !supported.includes(AgentVaultOauthClientAuthMethod.ClientSecretBasic) &&
  supported.includes(AgentVaultOauthClientAuthMethod.ClientSecretPost)
    ? AgentVaultOauthClientAuthMethod.ClientSecretPost
    : AgentVaultOauthClientAuthMethod.ClientSecretBasic;

// RFC 7591. Servers must ignore metadata fields they don't understand, so the only one a strict server can refuse
// is `application_type` (an OIDC registration value); a refusal is retried once without it. `grant_types` stays,
// or a strict server registers authorization_code only and every refresh fails with unauthorized_client. It drops
// refresh_token only when the server's metadata lists its grants without it, since a strict one refuses the request.
// It asks for a public client unless the server lists its auth methods without `none`, for the same reason.
export const registerOauthClient = async ({
  http,
  serverUrl,
  registrationEndpoint,
  redirectUri,
  grantTypesSupported,
  tokenEndpointAuthMethodsSupported
}: {
  http: TOauthHttpClient;
  serverUrl: string;
  registrationEndpoint: string;
  redirectUri: string;
  grantTypesSupported: string[] | null;
  tokenEndpointAuthMethodsSupported: string[] | null;
}): Promise<{ client: TOauthClient; compatibility: AgentVaultOauthCompatibility[] }> => {
  const refreshSupported = !grantTypesSupported || grantTypesSupported.includes(OauthGrantType.RefreshToken);
  const publicClientSupported =
    !tokenEndpointAuthMethodsSupported ||
    tokenEndpointAuthMethodsSupported.includes(AgentVaultOauthClientAuthMethod.None);
  const minimal = {
    client_name: AGENT_VAULT_OAUTH_CLIENT_NAME,
    redirect_uris: [redirectUri],
    token_endpoint_auth_method: publicClientSupported
      ? AgentVaultOauthClientAuthMethod.None
      : secretAuthMethod(tokenEndpointAuthMethodsSupported),
    grant_types: refreshSupported
      ? [OauthGrantType.AuthorizationCode, OauthGrantType.RefreshToken]
      : [OauthGrantType.AuthorizationCode],
    response_types: ["code"]
  };
  const full = { ...minimal, application_type: "web" };

  const deadline = Date.now() + REGISTRATION_BUDGET_MS;
  let lastStatus: number | null = null;
  let lastReason = "";
  // eslint-disable-next-line no-restricted-syntax
  for (const [attempt, body] of [full, minimal].entries()) {
    let response;
    try {
      // eslint-disable-next-line no-await-in-loop
      response = await withTimeout(http.postJson(registrationEndpoint, body), Math.max(1, deadline - Date.now()));
    } catch {
      logger.info(`agentVaultOauth: client registration unreachable [server=${describeServer(serverUrl)}]`);
      throw new OauthRegistrationError("its registration endpoint couldn't be reached.", null);
    }
    lastStatus = response.status;
    try {
      const refusal = JSON.parse(response.body) as { error?: unknown; error_description?: unknown };
      lastReason =
        normalizeProviderText(refusal.error_description, MAX_ERROR_DESCRIPTION_LENGTH) ||
        normalizeProviderText(refusal.error, MAX_ERROR_CODE_LENGTH);
    } catch {
      lastReason = "";
    }
    if (response.status === 200 || response.status === 201) {
      const client = parseRegistration(response.body, minimal.token_endpoint_auth_method);
      if (!client) {
        throw new OauthRegistrationError("its registration endpoint returned no usable client ID.", response.status);
      }
      return {
        client,
        compatibility: attempt === 0 ? [] : [AgentVaultOauthCompatibility.RegistrationMinimal]
      };
    }
    logger.info(
      `agentVaultOauth: client registration refused [server=${describeServer(serverUrl)}] [status=${response.status}] [attempt=${attempt + 1}]`
    );
    if (response.status >= 500) break;
  }

  throw new OauthRegistrationError(
    `its registration endpoint refused to register Infisical as a client (${lastReason || `HTTP ${lastStatus}`}).`,
    lastStatus
  );
};

// An admin-entered client.
export const manualOauthClient = ({
  clientId,
  clientSecret,
  tokenEndpointAuthMethodsSupported
}: {
  clientId: string;
  clientSecret?: string;
  tokenEndpointAuthMethodsSupported: string[] | null;
}): TOauthClient => {
  if (!clientSecret) return { clientId, tokenEndpointAuthMethod: AgentVaultOauthClientAuthMethod.None };
  return { clientId, clientSecret, tokenEndpointAuthMethod: secretAuthMethod(tokenEndpointAuthMethodsSupported) };
};

