import { S3ServiceException } from "@aws-sdk/client-s3";
import { describe, expect, test } from "vitest";

import { ObjectStorageError, toObjectStorageError } from "./object-storage-errors";
import { ObjectStorageErrorReason, ObjectStorageType } from "./object-storage-types";

const wrap = (error: unknown, storageType = ObjectStorageType.External) =>
  toObjectStorageError(error, { storageType, bucket: "logs", region: "us-east-1" });
const s3Error = (name: string, fault: "client" | "server" = "client", httpStatusCode?: number) =>
  new S3ServiceException({ name, $fault: fault, $metadata: { httpStatusCode }, message: name });

describe("toObjectStorageError", () => {
  test.each([
    { error: s3Error("SlowDown"), reason: ObjectStorageErrorReason.Temporary },
    { error: s3Error("SomethingNew", "server", 503), reason: ObjectStorageErrorReason.Temporary },
    { error: Object.assign(new Error("connect"), { code: "ECONNRESET" }), reason: ObjectStorageErrorReason.Temporary },
    { error: s3Error("AccessDenied", "client", 403), reason: ObjectStorageErrorReason.AccessDenied },
    { error: s3Error("InvalidAccessKeyId"), reason: ObjectStorageErrorReason.CredentialsInvalid },
    { error: s3Error("NoSuchBucket", "client", 404), reason: ObjectStorageErrorReason.BucketNotFound },
    { error: s3Error("SomethingNew", "client", 400), reason: ObjectStorageErrorReason.Rejected }
  ])("reads $error.name as $reason", ({ error, reason }) => {
    const wrapped = wrap(error) as ObjectStorageError;
    expect(wrapped).toBeInstanceOf(ObjectStorageError);
    expect(wrapped.reason).toBe(reason);
    const label = (error as { code?: string }).code ?? error.name;
    expect(wrapped.details).toMatchObject({ bucket: "logs", region: "us-east-1", awsErrorCode: label });
  });

  test("leaves an error that didn't come from storage as it is", () => {
    const bug = new TypeError("a bug");
    expect(wrap(bug)).toBe(bug);
  });

  test("reads default storage with no usable credentials as invalid credentials, not a bug", () => {
    const missing = Object.assign(new Error("Could not load credentials from any providers"), {
      name: "CredentialsProviderError"
    });
    const wrapped = wrap(missing, ObjectStorageType.Default) as ObjectStorageError;
    expect(wrapped.reason).toBe(ObjectStorageErrorReason.CredentialsInvalid);
    expect(wrapped.storageType).toBe(ObjectStorageType.Default);
  });

  test("keeps an error that is already a storage error", () => {
    const existing = new ObjectStorageError({
      reason: ObjectStorageErrorReason.ConnectionInvalid,
      storageType: ObjectStorageType.External
    });
    expect(wrap(existing)).toBe(existing);
  });
});

import { describe, expect, test } from "vitest";

import { ProjectType } from "@app/db/schemas";

import { assertNamespacesValid, defineStorageNamespace } from "./object-storage-namespace-fns";

const ns = (id: string, path: string, product = ProjectType.AgentVault) =>
  defineStorageNamespace({ id, product, path });

describe("defining a namespace", () => {
  test("its path must end in {file}", () => {
    expect(() => ns("a", "sessions/{sessionId}/logs")).toThrow("must end in /{file}");
  });

  test("its pieces are fixed words or {ids}", () => {
    expect(() => ns("a", "sessions/{session id}/logs/{file}")).toThrow();
    expect(ns("a", "sessions/{sessionId}/logs/{file}").segments).toEqual([
      { kind: "word", value: "sessions" },
      { kind: "id", name: "sessionId" },
      { kind: "word", value: "logs" }
    ]);
  });
});

describe("the startup checks", () => {
  test.each([
    { why: "words and ids take turns", path: "sessions/{sessionId}/logs/{file}" },
    { why: "many ids may follow the last word", path: "monthly/{year}/{month}/{day}/{file}" },
    { why: "a single word", path: "exports/{file}" }
  ])("accepts a path where $why", ({ path }) => {
    expect(() => assertNamespacesValid([ns("a", path)])).not.toThrow();
  });

  test.each([
    {
      why: "two words in a row, so an id could equal the second word",
      path: "requests/exports/{exportId}/{file}"
    },
    { why: "an id before any word", path: "{sessionId}/logs/{file}" },
    { why: "two ids before the last word", path: "sessions/{a}/{b}/logs/{file}" },
    { why: "no fixed word at all", path: "{file}" }
  ])("refuses a path with $why", ({ path }) => {
    expect(() => assertNamespacesValid([ns("a", path)])).toThrow();
  });

  test("refuses a namespace whose last word another namespace of the product uses", () => {
    expect(() =>
      assertNamespacesValid([
        ns("agent-vault.session-logs", "sessions/{sessionId}/logs/{file}"),
        ns("agent-vault.attachments", "sessions/{sessionId}/{file}")
      ])
    ).toThrow('ends in "sessions"');
  });

  test("allows a word of its own beside another namespace", () => {
    expect(() =>
      assertNamespacesValid([
        ns("agent-vault.session-logs", "sessions/{sessionId}/logs/{file}"),
        ns("agent-vault.attachments", "sessions/{sessionId}/attachments/{file}")
      ])
    ).not.toThrow();
  });

  test("products don't constrain each other", () => {
    expect(() =>
      assertNamespacesValid([
        ns("agent-vault.session-logs", "sessions/{sessionId}/logs/{file}"),
        ns("pam.recordings", "sessions/{sessionId}/{file}", ProjectType.PAM)
      ])
    ).not.toThrow();
  });

  test("refuses the same id twice", () => {
    expect(() => assertNamespacesValid([ns("a", "x/{file}"), ns("a", "y/{file}")])).toThrow("registered twice");
  });
});

import { describe, expect, test } from "vitest";

import { ProjectType } from "@app/db/schemas";

import { defineStorageNamespace } from "./object-storage-namespace-fns";
import { assertSafePiece, buildNamespaceFolder, buildObjectKey, buildProductFolder } from "./object-storage-path-fns";

const ORG_ID = "c4a1e0d2-5b7f-4c1e-9a3d-2f6b8e0c7a11";
const logs = defineStorageNamespace({
  id: "agent-vault.session-logs",
  product: ProjectType.AgentVault,
  path: "sessions/{sessionId}/logs/{file}"
});

describe("object paths", () => {
  test("a product folder starts with the prefix and the org, so no product can write into another org's files", () => {
    expect(buildProductFolder({ prefix: "infisical", orgId: ORG_ID, product: "agent-vault" })).toBe(
      `infisical/orgs/${ORG_ID}/agent-vault/`
    );
    expect(buildProductFolder({ prefix: null, orgId: ORG_ID, product: "agent-vault" })).toBe(
      `orgs/${ORG_ID}/agent-vault/`
    );
  });

  test("a namespace folder fills in its ids after the product folder", () => {
    const productFolder = buildProductFolder({ orgId: ORG_ID, product: "agent-vault" });
    expect(buildNamespaceFolder(productFolder, logs, { sessionId: "sess-1" })).toBe(
      `orgs/${ORG_ID}/agent-vault/sessions/sess-1/logs/`
    );
  });

  test("a missing id is refused", () => {
    expect(() => buildNamespaceFolder("orgs/x/agent-vault/", logs, {})).toThrow("Missing 'sessionId'");
  });

  test.each(["..", ".", "a/b", "", "a".repeat(129), "sess 1", "sess.1"])("refuses the id %j", (id) => {
    expect(() => assertSafePiece(id, "id")).toThrow();
  });

  test.each(["..", ".", "a/b", "", "a".repeat(129)])("refuses the file name %j", (name) => {
    expect(() => assertSafePiece(name, "file")).toThrow();
  });

  test("a file name may have dots inside it", () => {
    expect(() => assertSafePiece("8208694117999_abc.def.json.enc", "file")).not.toThrow();
  });

  test("a full path over 1,024 bytes is refused", () => {
    expect(() => buildObjectKey(`${"a/".repeat(500)}`, "a".repeat(100))).toThrow("longer than 1024 bytes");
  });
});

package access_test

import (
	"net/http"
	"testing"

	"github.com/Infisical/infisical/tests/clients/api"
	"github.com/Infisical/infisical/tests/fixture"
	"github.com/Infisical/infisical/tests/fixture/secretmanager"
	"github.com/Infisical/infisical/tests/harness"
	"github.com/Infisical/infisical/tests/harness/infisical"
	"github.com/stretchr/testify/require"
)

func TestPrincipal_ProjectAccess(t *testing.T) {
	t.Parallel()
	h := harness.From(t)

	t.Run("should refuse an org admin who is not a project member", func(t *testing.T) {
		t.Parallel()

		// Setup
		tn := h.NewTenant(t)
		proj := fixture.NewProject(t, tn, fixture.WithProjectType("secret-manager"))
		orgAdmin := tn.NewUser(t, harness.OrgRole("admin"))

		// Action
		res := listSecrets(t, orgAdmin.API, proj, "dev", "/")

		// Assert
		require.Equal(t, http.StatusForbidden, res.StatusCode())
		require.Contains(t, string(res.Body), "You are not a member of this project")
		require.Nil(t, userRoles(t, proj, orgAdmin))
	})

	t.Run("should make an org admin a project admin through grant-admin-access and record it", func(t *testing.T) {
		t.Parallel()

		// Setup
		tn := h.NewTenant(t)
		proj := fixture.NewProject(t, tn, fixture.WithProjectType("secret-manager"))
		orgAdmin := tn.NewUser(t, harness.OrgRole("admin"))

		// Action
		res, err := orgAdmin.API.GrantOrganizationAdminProjectAccessWithResponse(t.Context(), proj.ID)

		// Assert
		require.NoError(t, err)
		requireStatus(t, http.StatusOK, res.StatusCode(), res.Body)
		require.Equal(t, []string{"admin"}, slugs(userRoles(t, proj, orgAdmin)))
		created := createSecret(t, orgAdmin.API, proj, "dev", "/", "NEW", "value")
		requireStatus(t, http.StatusOK, created.StatusCode(), created.Body)
		event := auditEvent(t, tn, "org-admin-accessed-project", func(m map[string]any) bool {
			return m["projectId"] == proj.ID
		})
		require.Equal(t, orgAdmin.ID.String(), event["userId"])
	})

	t.Run("should refuse grant-admin-access to an org member and add no membership", func(t *testing.T) {
		t.Parallel()

		// Setup
		tn := h.NewTenant(t)
		proj := fixture.NewProject(t, tn, fixture.WithProjectType("secret-manager"))
		member := tn.NewUser(t, harness.OrgRole("member"))

		// Action
		res, err := member.API.GrantOrganizationAdminProjectAccessWithResponse(t.Context(), proj.ID)

		// Assert
		require.NoError(t, err)
		require.Equal(t, http.StatusForbidden, res.StatusCode())
		require.Nil(t, userRoles(t, proj, member))
	})

	t.Run("should refuse an identity once it is removed from the project", func(t *testing.T) {
		t.Parallel()

		// Setup
		tn := h.NewTenant(t)
		proj := fixture.NewProject(t, tn, fixture.WithProjectType("secret-manager"))
		secretmanager.CreateSecret(t, proj, "dev", "EXISTING", "value")
		identity := tn.NewMachineIdentity(t)
		proj.Grant(t, identity, "viewer")
		before := listSecrets(t, identity.API, proj, "dev", "/")
		requireStatus(t, http.StatusOK, before.StatusCode(), before.Body)

		// Action
		res, err := tn.Admin.API.DeleteProjectIdentityMembershipWithResponse(t.Context(), proj.ID, identity.ID.String())

		// Assert
		require.NoError(t, err)
		requireStatus(t, http.StatusOK, res.StatusCode(), res.Body)
		body := waitForStatus(t, http.StatusForbidden, func() (int, []byte) {
			r := listSecrets(t, identity.API, proj, "dev", "/")
			return r.StatusCode(), r.Body
		})
		require.Contains(t, string(body), "You are not a member of this project")
	})

	t.Run("should refuse a deleted identity's token as unauthenticated", func(t *testing.T) {
		t.Parallel()

		// Setup
		tn := h.NewTenant(t)
		proj := fixture.NewProject(t, tn, fixture.WithProjectType("secret-manager"))
		identity := tn.NewMachineIdentity(t)
		proj.Grant(t, identity, "viewer")

		// Action
		res, err := tn.Admin.API.DeleteMachineIdentityWithResponse(t.Context(), identity.ID.String())

		// Assert
		require.NoError(t, err)
		requireStatus(t, http.StatusOK, res.StatusCode(), res.Body)
		waitForStatus(t, http.StatusUnauthorized, func() (int, []byte) {
			r := listSecrets(t, identity.API, proj, "dev", "/")
			return r.StatusCode(), r.Body
		})
	})
}

func TestPrincipal_TrustedIPs(t *testing.T) {
	t.Parallel()
	h := harness.From(t)

	t.Run("should refuse an identity token used from outside its trusted IPs and accept it from inside", func(t *testing.T) {
		t.Parallel()

		// Setup
		tn := h.NewTenant(t)
		proj := fixture.NewProject(t, tn, fixture.WithProjectType("secret-manager"))
		secretmanager.CreateSecret(t, proj, "dev", "EXISTING", "value")
		trusted := sourceIP()
		identity := identityTrustedFrom(t, tn, trusted)
		proj.Grant(t, identity, "viewer")
		outside := tn.Client(t, identity.Token, infisical.ForwardedFor(sourceIP()))

		// Action
		res := listSecrets(t, outside, proj, "dev", "/")

		// Assert
		require.Equal(t, http.StatusForbidden, res.StatusCode())
		require.Contains(t, string(res.Body), "You are not allowed to access this resource from the current IP address")
		inside := listSecrets(t, identity.API, proj, "dev", "/")
		requireStatus(t, http.StatusOK, inside.StatusCode(), inside.Body)
		require.Equal(t, []string{"EXISTING"}, keysOf(inside))
	})
}

// identityTrustedFrom creates an org identity whose access tokens are valid only from
// one address, logged in from that address. Its API sends that address.
func identityTrustedFrom(t *testing.T, tn *harness.Tenant, ip string) *harness.Principal {
	t.Helper()
	ctx, admin := t.Context(), tn.Admin.API
	name := "trusted-" + ip

	created, err := admin.CreateMachineIdentityWithResponse(ctx, api.CreateMachineIdentityJSONRequestBody{
		Name: name, OrganizationId: tn.OrgID.String(), Role: new("member"),
	})
	require.NoError(t, err)
	require.NotNilf(t, created.JSON200, "creating identity returned %d: %s", created.StatusCode(), created.Body)
	identityID := created.JSON200.Identity.Id

	trustedIPs := []struct {
		IpAddress string `json:"ipAddress"`
	}{{IpAddress: ip + "/32"}}
	attached, err := admin.AttachUniversalAuthWithResponse(ctx, identityID.String(), api.AttachUniversalAuthJSONRequestBody{
		AccessTokenTrustedIps: &trustedIPs,
	})
	require.NoError(t, err)
	require.NotNilf(t, attached.JSON200, "attaching universal auth returned %d: %s", attached.StatusCode(), attached.Body)

	secret, err := admin.CreateUniversalAuthClientSecretWithResponse(ctx, identityID.String(),
		api.CreateUniversalAuthClientSecretJSONRequestBody{})
	require.NoError(t, err)
	require.NotNilf(t, secret.JSON200, "creating a client secret returned %d: %s", secret.StatusCode(), secret.Body)

	login, err := tn.Anonymous(t, infisical.ForwardedFor(ip)).LoginWithUniversalAuthWithResponse(ctx,
		api.LoginWithUniversalAuthJSONRequestBody{
			ClientId:         attached.JSON200.IdentityUniversalAuth.ClientId,
			ClientSecret:     [REDACTED],
			OrganizationSlug: &tn.OrgSlug,
		})
	require.NoError(t, err)
	require.NotNilf(t, login.JSON200, "logging in returned %d: %s", login.StatusCode(), login.Body)

	token := login.JSON200.AccessToken
	return &harness.Principal{
		Kind:  harness.MachineIdentity,
		ID:    identityID,
		Name:  name,
		Token: token,
		API:   tn.Client(t, token, infisical.ForwardedFor(ip)),
	}
}

package servicetokens_test

import (
	"bytes"
	"context"
	"encoding/json"
	"testing"

	"github.com/Infisical/infisical/tests/clients/api"
	"github.com/Infisical/infisical/tests/fixture"
	"github.com/Infisical/infisical/tests/fixture/secretmanager"
	"github.com/Infisical/infisical/tests/harness"
	"github.com/Infisical/infisical/tests/internal/apierr"
	"github.com/Infisical/infisical/tests/internal/wait"
	"github.com/stretchr/testify/require"
)

type tokenScope struct {
	Environment string `json:"environment"`
	SecretPath  string `json:"secretPath"`
}

type tokenOptions struct {
	scopes      []tokenScope
	permissions []string
	expiresIn   *int
}

// requestServiceToken asks for a service token as creator. The key material is
// opaque to the server on a project that is not end-to-end encrypted.
func requestServiceToken(t *testing.T, creator *harness.Principal, proj *fixture.Project, opts tokenOptions) *api.CreateServiceTokenResponse {
	t.Helper()
	raw, err := json.Marshal(map[string]any{
		"name":         "token",
		"workspaceId":  proj.ID,
		"scopes":       opts.scopes,
		"permissions":  opts.permissions,
		"expiresIn":    opts.expiresIn,
		"encryptedKey": "unused",
		"iv":           "unused",
		"tag":          "unused",
	})
	require.NoError(t, err)
	res, err := creator.API.CreateServiceTokenWithBodyWithResponse(t.Context(), "application/json", bytes.NewReader(raw))
	require.NoError(t, err)
	return res
}

func newServiceToken(t *testing.T, proj *fixture.Project, opts tokenOptions) *api.ClientWithResponses {
	t.Helper()
	res := requestServiceToken(t, proj.Tenant().Admin, proj, opts)
	require.NotNilf(t, res.JSON200, "creating a service token returned %d: %s", res.StatusCode(), apierr.Body(res.Body))
	return proj.Tenant().Client(t, res.JSON200.ServiceToken)
}

func serviceTokenCount(t *testing.T, proj *fixture.Project) int {
	t.Helper()
	res, err := proj.Tenant().Admin.API.ListProjectServiceTokensWithResponse(t.Context(), proj.ID)
	require.NoError(t, err)
	require.NotNilf(t, res.JSON200, "listing service tokens returned %d: %s", res.StatusCode(), apierr.Body(res.Body))
	return len(res.JSON200.ServiceTokenData)
}

func valuesAt(t *testing.T, proj *fixture.Project, secretPath string) map[string]string {
	t.Helper()
	values := map[string]string{}
	for _, s := range secretmanager.ListSecrets(t, proj, "dev", secretmanager.WithPath(secretPath)) {
		values[s.Key] = s.Value
	}
	return values
}

func createSecret(t *testing.T, actor *api.ClientWithResponses, proj *fixture.Project, env, secretPath, name, value string, editors ...api.RequestEditorFn) *api.CreateSecretV4Response {
	t.Helper()
	res, err := actor.CreateSecretV4WithResponse(t.Context(), name, api.CreateSecretV4JSONRequestBody{
		ProjectId:   proj.ID,
		Environment: env,
		SecretPath:  &secretPath,
		SecretValue: value,
	}, editors...)
	require.NoError(t, err)
	return res
}

func listSecrets(t *testing.T, actor *api.ClientWithResponses, proj *fixture.Project, env, secretPath string, editors ...api.RequestEditorFn) *api.ListSecretsV4Response {
	t.Helper()
	res, err := actor.ListSecretsV4WithResponse(t.Context(), &api.ListSecretsV4Params{
		ProjectId:       &proj.ID,
		Environment:     &env,
		SecretPath:      &secretPath,
		ViewSecretValue: new(api.ListSecretsV4ParamsViewSecretValueTrue),
	}, editors...)
	require.NoError(t, err)
	return res
}

func keysOf(res *api.ListSecretsV4Response) []string {
	keys := []string{}
	if res.JSON200 == nil {
		return keys
	}
	for _, s := range res.JSON200.Secrets {
		keys = append(keys, s.SecretKey)
	}
	return keys
}

// waitForStatus polls a call until it answers with the wanted status. Membership and
// role changes reach the permission cache up to 10 seconds late.
func waitForStatus(t *testing.T, want int, call func() (int, []byte)) []byte {
	t.Helper()
	var last []byte
	_, err := wait.For(t.Context(), func(context.Context) (struct{}, bool, error) {
		status, body := call()
		last = body
		return struct{}{}, status == want, nil
	})
	require.NoErrorf(t, err, "waiting for %d, last body: %s", want, apierr.Body(last))
	return last
}

func requireStatus(t *testing.T, want, got int, body []byte) {
	t.Helper()
	require.Equalf(t, want, got, "answered %d: %s", got, apierr.Body(body))
}

package servicetokens_test

import (
